public static Kiste entferneLeichteste(DynArray d) {
    if (d.isEmpty()) {
        return null;
    }
    int minIndex = 0;
    for (int i = 1; i <= d.getLength(); i++) {
        Kiste k = (Kiste) d.getItem(i);
        if (k.getGewicht() < ((Kiste) d.getItem(minIndex)).getGewicht()) {
            minIndex = i;
        }
    }
    Kiste leicht = (Kiste) d.getItem(minIndex);
    d.delete(minIndex);
    return leicht;
}

