static class ZweiStapelSchlange {
    private Stack ein = new Stack();
    private Stack aus = new Stack();
    int umgeschichtet = 0;

    public void enqueue(Object x) {
        ein.push(x);
    }

    public Object dequeue() {
        if (aus.isEmpty()) {
            while (!ein.isEmpty()) {
                aus.push(ein.pop());
                umgeschichtet++;
            }
        }
        return aus.pop();
    }
}

