public static void umordnen(Queue q, int n) {
    Queue hilf = new Queue();
    for (int i = 0; i < n; i++) {
        int t = (Integer) q.dequeue();
        if (t % 2 == 0) {
            hilf.enqueue(t);
        } else {
            q.enqueue(t);
        }   // → Tabellenzeile
    }
    while (!hilf.isEmpty()) {
        q.enqueue(hilf.dequeue());
    }
}

